class Solution:
    def findMislabel(self, labels: List[int]) -> List[int]:
        dup = missing = -1
        for x in range(1, len(labels) + 1):
            c = labels.count(x)
            if c == 2:
                dup = x
            elif c == 0:
                missing = x
        return [dup, missing]

