class Solution {
    public int[] findMislabel(int[] labels) {
        int n = labels.length, dup = -1, missing = -1;
        for (int x = 1; x <= n; x++) {
            int c = 0;
            for (int v : labels) if (v == x) c++;
            if (c == 2) dup = x;
            else if (c == 0) missing = x;
        }
        return new int[] {dup, missing};
    }
}

