class Solution:
    def findMislabel(self, labels: List[int]) -> List[int]:
        a = labels
        i = 0
        while i < len(a):
            j = a[i] - 1
            if a[i] != a[j]:
                a[i], a[j] = a[j], a[i]
            else:
                i += 1
        for p, v in enumerate(a):
            if v != p + 1:
                return [v, p + 1]
        return [-1, -1]

