class Solution {
    public int[] findMislabel(int[] labels) {
        int[] a = labels;
        int i = 0;
        while (i < a.length) {
            int j = a[i] - 1;
            if (a[i] != a[j]) {
                int t = a[i]; a[i] = a[j]; a[j] = t;
            } else {
                i++;
            }
        }
        for (int p = 0; p < a.length; p++) {
            if (a[p] != p + 1) return new int[] {a[p], p + 1};
        }
        return new int[] {-1, -1};
    }
}

