class Solution {
    public int[] findMislabel(int[] labels) {
        long n = labels.length, total = 0, squares = 0;
        for (int v : labels) {
            total += v;
            squares += (long) v * v;
        }
        long diff = total - n * (n + 1) / 2;
        long sqDiff = squares - n * (n + 1) * (2 * n + 1) / 6;
        long both = sqDiff / diff;
        long dup = (diff + both) / 2;
        return new int[] {(int) dup, (int) (both - dup)};
    }
}

